    [RelayCommand]
    // @port: Daqifi.Desktop.ViewModels.DeviceLogsViewModel.ImportFile
    private async Task ImportFile(SdCardFile? file)
    {
        // Snapshot the device up front so a selection change during the async import can't retarget
        // it or misattribute a failure to a different device's drawer.
        var device = SelectedDevice;
        if (file == null || device == null || !CanAccessSdCard) return;

        try
        {
            IsBusy = true;
            BusyMessage = $"Downloading {file.FileName}...";

            var importer = ResolveImporter();

            var progress = new Progress<ImportProgress>(p =>
            {
                BusyMessage = $"Importing {file.FileName}... {p.SamplesProcessed:N0} samples";
            });

            var result = await Task.Run(() =>
                importer.ImportFromDeviceAsync(device, file.FileName, null, progress, CancellationToken.None));

            string message;
            if (result.SessionPersisted)
            {
                AddImportedSession(result.Session);
                message = $"Successfully imported {file.FileName}";

                // A persisted session can still owe the user a word — an overwrite whose old
                // session could not be removed leaves a duplicate they have to clear by hand.
                if (result.OutcomeGuidance.Length > 0)
                {
                    message += $"\n\n{result.OutcomeGuidance}";
                }
            }
            else
            {
                // Nothing threw, but no finished session came of it — an empty log, or samples
                // that could not be recorded as a completed session. The importer says which;
                // reporting a successful import here would name a session that is not there, or
                // is there flagged as incomplete.
                message = $"{file.FileName}: {result.OutcomeGuidance}";
            }

            var timestampWarning = result.TimestampQuality.BuildUserWarning();
            if (timestampWarning != null)
            {
                message += $"\n\nWarning: {timestampWarning}";
            }

            await ShowMessage("Import Complete", message, MessageBoxButton.OK);
        }
        catch (OperationCanceledException)
        {
            // User cancelled
        }
        catch (Exception ex)
        {
            var failure = HandleImportFailure(ex, file.FileName, device);
            await ShowMessage("Import Failed",
                $"Could not import {file.FileName}.\n\n{failure.Guidance}",
                MessageBoxButton.OK);
        }
        finally
        {
            IsBusy = false;
            BusyMessage = string.Empty;
        }
    }

    [RelayCommand]
    // @port: Daqifi.Desktop.ViewModels.DeviceLogsViewModel.ImportAllFiles
    private async Task ImportAllFiles()
    {
        // Snapshot the device up front (see ImportFile).
        var device = SelectedDevice;
        if (device == null || !CanAccessSdCard || DeviceFiles == null || !DeviceFiles.Any()) return;

        var filesToImport = DeviceFiles.ToList();
        var outcome = new ImportAllOutcome { TotalCount = filesToImport.Count };

        try
        {
            IsBusy = true;

            var importer = ResolveImporter();

            for (var i = 0; i < filesToImport.Count; i++)
            {
                // Re-check connectivity every iteration, not just once before the loop: the device
                // can go away mid-batch, and CoreDevice stays non-null, so the downstream null-guard
                // still passes and each remaining file would be issued against a dead transport.
                //
                // Covers a disconnect Core actually reports — an explicit Disconnect(), a USB
                // removal, or a transport-signalled loss (Core's ConnectionStatus.Lost). It does NOT
                // cover a fully silent TCP death: Core's TcpStreamTransport raises StatusChanged
                // only from its connect-failure and DisconnectAsync paths (no read-error hook or
                // keepalive), so IsConnected stays true and this check cannot see it. That case is
                // caught instead by the download stall watchdog, whose SdCardTransferStalledException
                // classifies card-unavailable and breaks below — costing one stall timeout for the
                // batch rather than one per remaining file.
                if (!device.IsConnected)
                {
                    outcome.DisconnectedMidBatch = true;
                    break;
                }

                var file = filesToImport[i];
                BusyMessage = $"Importing file {i + 1} of {filesToImport.Count}: {file.FileName}...";

                try
                {
                    var progress = new Progress<ImportProgress>(p =>
                    {
                        BusyMessage = $"Importing {file.FileName} ({i + 1}/{filesToImport.Count})... {p.SamplesProcessed:N0} samples";
                    });

                    var result = await Task.Run(() =>
                        importer.ImportFromDeviceAsync(device, file.FileName, null, progress, CancellationToken.None));

                    if (!result.SessionPersisted)
                    {
                        // Nothing threw, but no finished session came of it — usually an empty log,
                        // which is what an interrupted logging session leaves on the card and needs
                        // no attention paid to the device. It belongs in the skipped list; counting
                        // it as imported would put a session in the summary's total that the user
                        // will never find. The guidance sentence comes from the importer so this
                        // and the single-file dialog cannot say different things, and carries no
                        // file name so a card full of empty logs reads it out once.
                        outcome.RecordSkip(file.FileName, result.OutcomeGuidance);
                        continue;
                    }

                    AddImportedSession(result.Session);

                    // Imported, and still with something to say — an overwrite whose old session
                    // could not be removed. Not a skip (the file did import), so it gets its own
                    // line in the summary rather than being counted as one.
                    if (result.OutcomeGuidance.Length > 0)
                    {
                        outcome.RecordNotice(result.OutcomeGuidance);
                    }

                    if (result.TimestampQuality.HasDegenerateTimeAxis)
                    {
                        outcome.TimestampWarningCount++;
                    }

                    outcome.ImportedCount++;
                }
                catch (Exception ex)
                {
                    var failure = HandleImportFailure(ex, file.FileName, device);

                    // The SD subsystem is unusable, not just this one file — every remaining file
                    // would fail the same multi-second way, so stop rather than grinding through them.
                    if (failure.IsCardUnavailable)
                    {
                        outcome.AbortingFailure = failure;
                        outcome.AbortedOnFile = file.FileName;
                        break;
                    }

                    // Anything else may be specific to this file — an empty log, one corrupt
                    // directory entry, a rejected command. Skip it and keep going, and name it in
                    // the summary so the user can retry it on its own.
                    outcome.RecordSkip(file.FileName, failure.Guidance);
                }
            }

            await ShowMessage("Import Complete", BuildImportAllSummary(outcome), MessageBoxButton.OK);
        }
        catch (Exception ex)
        {
            _logger.Error(ex, "Error importing all files");
            await ShowMessage("Import Failed",
                "Import failed. Please check the device connection and try again.",
                MessageBoxButton.OK);
        }
        finally
        {
            IsBusy = false;
            BusyMessage = string.Empty;
        }
    }

    /// <summary>
    /// How many skipped file names the completion dialog lists before collapsing the rest into a
    /// count. A card carrying dozens of empty logs would otherwise produce a dialog taller than
    /// the screen.
    /// </summary>
    // @port: Daqifi.Desktop.ViewModels.DeviceLogsViewModel.MAX_LISTED_SKIPPED_FILES
    private const int MAX_LISTED_SKIPPED_FILES = 5;

    /// <summary>
    /// Builds the text of the "Import Complete" dialog from what the batch actually did.
    ///
    /// Skipped files are reported as skipped, by name, with the advice that applies to them — not
    /// as a card-wide abort, and not as a bare "N file(s) failed to import." with no way to tell
    /// which. Telling the user to power-cycle the device because one log file was empty sent them
    /// after a fault that was not there and hid the fact that every other file imported fine.
    /// </summary>
    /// <param name="outcome">What the batch imported, skipped, and stopped at.</param>
    /// <returns>The message body shown in the completion dialog.</returns>
    // @port: Daqifi.Desktop.ViewModels.DeviceLogsViewModel.BuildImportAllSummary
    internal static string BuildImportAllSummary(ImportAllOutcome outcome)
    {
        ArgumentNullException.ThrowIfNull(outcome);

        var message = new StringBuilder();
        message.Append(CultureInfo.CurrentCulture, $"Imported {outcome.ImportedCount} of {outcome.TotalCount} files.");

        if (outcome.SkippedFiles.Count > 0)
        {
            message.Append(CultureInfo.CurrentCulture, $"\n\nSkipped {outcome.SkippedFiles.Count} file(s).");
            message.Append(" You can retry any of them on their own from the file list.");

            foreach (var fileName in outcome.SkippedFiles.Take(MAX_LISTED_SKIPPED_FILES))
            {
                message.Append(CultureInfo.CurrentCulture, $"\n  • {fileName}");
            }

            var undisplayed = outcome.SkippedFiles.Count - MAX_LISTED_SKIPPED_FILES;
            if (undisplayed > 0)
            {
                message.Append(CultureInfo.CurrentCulture, $"\n  • ...and {undisplayed} more");
            }

            // One line per distinct reason: a card holding both an empty log and a corrupt one
            // needs both pieces of advice, but a card holding ten empty logs needs it once.
            foreach (var guidance in outcome.SkipGuidance)
            {
                message.Append(CultureInfo.CurrentCulture, $"\n\n{guidance}");
            }
        }

        // Deduped the same way, but about files that DID import — the batch is not going to name
        // them one by one, and the advice is the same for all of them.
        foreach (var notice in outcome.Notices)
        {
            message.Append(CultureInfo.CurrentCulture, $"\n\n{notice}");
        }

        if (outcome.DisconnectedMidBatch)
        {
            // Say so explicitly: without this a batch cut short by a disconnect reports the same
            // "Import Complete" summary as a finished one, and the user has no way to tell that
            // the untouched files were skipped rather than imported.
            message.Append("\n\nImport stopped early: the device disconnected. Reconnect and run ");
            message.Append("Import All again to pick up the remaining files.");
        }
        else if (outcome.AbortingFailure != null)
        {
            message.Append(CultureInfo.CurrentCulture,
                $"\n\nImport stopped at {outcome.AbortedOnFile}: {outcome.AbortingFailure.Guidance}");
        }

        if (outcome.TimestampWarningCount > 0)
        {
            message.Append(CultureInfo.CurrentCulture,
                $"\n\nWarning: {outcome.TimestampWarningCount} file(s) contain samples with no device");
            message.Append(" timestamp; those samples were placed at the session start time, so their");
            message.Append(" time spacing is not meaningful.");
        }

        return message.ToString();
    }

    // @port: Daqifi.Desktop.ViewModels.DeviceLogsViewModel.ResolveImporter
    private ISdCardSessionImporter ResolveImporter()
    {
        if (_importerOverride != null)
        {
            return _importerOverride;
        }

        var loggingContext = App.ServiceProvider.GetRequiredService<IDbContextFactory<LoggingContext>>();
        return new SdCardSessionImporter(loggingContext);
    }

    // @port: Daqifi.Desktop.ViewModels.DeviceLogsViewModel.AddImportedSession
    private static void AddImportedSession(LoggingSession session)
    {
        if (!Dispatcher.UIThread.CheckAccess())
        {
            Dispatcher.UIThread.Invoke(() => LoggingManager.Instance.LoggingSessions.Add(session));
        }
        else
        {
            LoggingManager.Instance.LoggingSessions.Add(session);
        }
    }

    // @port: Daqifi.Desktop.ViewModels.DeviceLogsViewModel.HandleImportFailure
    private SdCardFailure HandleImportFailure(Exception ex, string fileName, IStreamingDevice device)
    {
        var failure = SdCardFailureClassifier.Classify(ex);
        // Only paint the card-wide SD panel for a DEVICE-WIDE failure (IsCardUnavailable) that is still
        // the selected device. A per-file failure (empty file, one corrupt file, a momentary stall) is
        // surfaced by the import summary dialog instead — painting the card-wide Error panel for it
        // would hide the whole file list (HasFiles requires SdCardState==Ok) even though the batch keeps
        // going and later files import fine, leaving a sticky panel that contradicts the actual outcome.
        if (failure.IsExpectedDeviceCondition && failure.IsCardUnavailable && ReferenceEquals(SelectedDevice, device))
        {
            ApplyFailureState(failure);
        }
        LogFailure(ex, failure, $"Error importing {fileName} from device {device.DeviceSerialNo}");
        return failure;
    }

    // @port: Daqifi.Desktop.ViewModels.DeviceLogsViewModel.ApplyFailureState
    private void ApplyFailureState(SdCardFailure failure)
    {
        SdCardState = failure.State;
        SdCardErrorMessage = failure.StatusMessage;
        SdCardErrorGuidance = failure.Guidance;
    }

    // @port: Daqifi.Desktop.ViewModels.DeviceLogsViewModel.LogFailure
    private void LogFailure(Exception ex, SdCardFailure failure, string context)
    {
        // Expected device conditions (no card, wedged subsystem, filesystem error) log at Warning so
        // they do not raise Sentry issues; a genuine defect keeps the Error path.
        if (failure.IsExpectedDeviceCondition)
        {
            _logger.Warning(ex, $"{context}: {failure.Guidance}");
        }
        else
        {
            _logger.Error(ex, context);
        }
    }

    // @port: Daqifi.Desktop.ViewModels.DeviceLogsViewModel.ShowMessage
    // MahApps ShowMessageAsync on the MetroWindow → IMessageBoxService (dialog_service
    // mechanism); MessageDialogStyle.Affirmative maps to MessageBoxButton.OK.
    private async Task ShowMessage(string title, string message, MessageBoxButton button)
    {
        await _messageBoxService.ShowAsync(message, title, button, MessageBoxImage.Information);
    }

    private static readonly IMessageBoxService _messageBoxService = new AvaloniaMessageBoxService();
}

/// <summary>
/// What an "Import All" run did, in the terms its completion dialog reports. Accumulated as the
/// batch runs and handed to <see cref="DeviceLogsViewModel.BuildImportAllSummary"/>, which is
/// separated out so the wording can be unit-tested without a dialog or a device.
/// </summary>
// @port: Daqifi.Desktop.ViewModels.ImportAllOutcome
internal sealed class ImportAllOutcome
{
    private readonly List<string> _skippedFiles = [];
    private readonly List<string> _skipGuidance = [];
    private readonly List<string> _notices = [];

    /// <summary>How many files the batch started with.</summary>
    // @port: Daqifi.Desktop.ViewModels.ImportAllOutcome.TotalCount
    public int TotalCount { get; init; }

    /// <summary>How many files imported successfully.</summary>
    // @port: Daqifi.Desktop.ViewModels.ImportAllOutcome.ImportedCount
    public int ImportedCount { get; set; }

    /// <summary>How many imported sessions carried at least one substituted timestamp.</summary>
    // @port: Daqifi.Desktop.ViewModels.ImportAllOutcome.TimestampWarningCount
    public int TimestampWarningCount { get; set; }

    /// <summary>
    /// Files that failed for a reason that may be specific to them, in list order. The batch
    /// carried on past each of these, and the user can still retry them individually.
    /// </summary>
    // @port: Daqifi.Desktop.ViewModels.ImportAllOutcome.SkippedFiles
    public IReadOnlyList<string> SkippedFiles => _skippedFiles;

    /// <summary>
    /// The distinct guidance sentences the skipped files produced, in first-seen order. Deduped
    /// so ten empty logs read out their advice once rather than ten times.
    /// </summary>
    // @port: Daqifi.Desktop.ViewModels.ImportAllOutcome.SkipGuidance
    public IReadOnlyList<string> SkipGuidance => _skipGuidance;

    /// <summary>
    /// Things that need saying about files that DID import, in first-seen order and deduped.
    /// Downstream addition: an overwrite whose superseded session could not be removed leaves a
    /// duplicate the user has to clear, which is neither a skip nor a silence.
    /// </summary>
    public IReadOnlyList<string> Notices => _notices;

    /// <summary>Records a note about a file that imported successfully.</summary>
    /// <param name="notice">What the user should know. Deduped, so it must carry no file name.</param>
    public void RecordNotice(string notice)
    {
        if (!_notices.Contains(notice))
        {
            _notices.Add(notice);
        }
    }

    /// <summary>
    /// The card-wide failure that ended the batch early, or <c>null</c> if it ran to completion.
    /// </summary>
    // @port: Daqifi.Desktop.ViewModels.ImportAllOutcome.AbortingFailure
    public SdCardFailure? AbortingFailure { get; set; }

    /// <summary>The file the batch stopped at, set with <see cref="AbortingFailure"/>.</summary>
    // @port: Daqifi.Desktop.ViewModels.ImportAllOutcome.AbortedOnFile
    public string? AbortedOnFile { get; set; }

    /// <summary>
    /// True when the batch stopped because the device went away mid-run. Port-only: this app
    /// re-checks <c>IDevice.IsConnected</c> on every iteration, which upstream does not, and a
    /// batch cut short that way has no failing file to name.
    /// </summary>
    public bool DisconnectedMidBatch { get; set; }

    /// <summary>
    /// Records a file the batch skipped and carried on past.
    /// </summary>
    /// <param name="fileName">The file that failed.</param>
    /// <param name="guidance">What the user should do about it.</param>
    // @port: Daqifi.Desktop.ViewModels.ImportAllOutcome.RecordSkip
    public void RecordSkip(string fileName, string guidance)
    {
        _skippedFiles.Add(fileName);

        if (!_skipGuidance.Contains(guidance))
        {
            _skipGuidance.Add(guidance);
        }
    }
}
